p='tests/samples/'
files=[f for f in sorted(os.listdir(p)) if f.endswith('.xls') and f!='corrupted_error.xls']
for fn in files:
    for kw in ({}, {'formatting_info':True}, {'ragged_rows':True}, {'on_demand':True},
